import { defineMiddleware } from 'astro:middleware';
import { initializePicard } from 'picard-js/node';

/**
 * Picard.js renders the micro frontends into the pages generated by Astro.
 * The islands script resumes them in the browser.
 */
const picard = initializePicard({
  feed: 'https://feed.piral.cloud/api/v1/microfrontends/picard-demos',
  interactive: true,
  // the islands script is generated next to the pages (see src/pages/picard/[file].ts)
  scriptUrl: '/picard/picard.js',
});

// runs at build time for the statically generated pages
export const onRequest = defineMiddleware(async (_context, next) => {
  const response = await next();

  if (!response.headers.get('content-type')?.includes('text/html')) {
    return response;
  }

  const html = await picard.decorate(await response.text());
  return new Response(html, { status: response.status, headers: response.headers });
});
